namespace FolderScope {
 public class FileReportForm:Form {
  private MainForm owner;private Snapshot data,displayedData;private string displayedKind;private bool offline,displayedOffline;private ComboBox path,compare;private TableLayoutPanel location;private ListBox kinds;private NumericUpDown limit;private ReportGrid grid;private SizeChart chart;private Label status;private CancellationTokenSource cancel;private bool working;
  public FileReportForm(MainForm main,string initial){owner=main;data=main.Data;offline=displayedOffline=main.Offline;Text=L.T("File Reporter");Font=new Font("Segoe UI",9);Size=new Size(1120,750);MinimumSize=new Size(800,550);AutoScaleDimensions=new SizeF(96,96);AutoScaleMode=AutoScaleMode.Dpi;StartPosition=FormStartPosition.CenterParent;ShowIcon=false;
   var tool=new ToolStrip{Dock=DockStyle.Top,GripStyle=ToolStripGripStyle.Hidden,ImageScalingSize=new Size(UI.D(16),UI.D(16))};tool.Items.Add(UI.Tool("Start","play",()=>Generate(true)));tool.Items.Add(UI.Tool("Stop","stop",()=>{if(cancel!=null)cancel.Cancel();}));tool.Items.Add(new ToolStripSeparator());tool.Items.Add(UI.Tool("Print","print",()=>UI.Print(this,Text,grid.Data)));tool.Items.Add(UI.Tool("Export","export",()=>UI.Export(this,Text,grid.Data)));tool.Items.Add(UI.Tool("Options","settings",()=>{using(var f=new OptionsForm(owner.Settings,false))if(f.ShowDialog(this)==DialogResult.OK){owner.Settings=f.Result;owner.Settings.Save();}}));tool.Items.Add(UI.Tool("Task Scheduler","clock",()=>{using(var f=new ScheduleForm(owner.Settings,path.Text))f.ShowDialog(this);}));
   foreach(string op in new[]{"Copy","Move","Delete","Archive"}){string action=op;tool.Items.Add(UI.Tool(action,op=="Archive"?"zip":op=="Delete"?"delete":"file",()=>Operations.Execute(action,grid,displayedOffline||working,()=>Generate(true))));}
   var loc=location=new TableLayoutPanel{Dock=DockStyle.Top,AutoSize=true,AutoSizeMode=AutoSizeMode.GrowAndShrink,ColumnCount=2,Padding=new Padding(6,4,6,4)};loc.ColumnStyles.Add(new ColumnStyle(SizeType.Percent,100));loc.ColumnStyles.Add(new ColumnStyle(SizeType.AutoSize));path=new ComboBox{Anchor=AnchorStyles.Left|AnchorStyles.Right,Text=main.CurrentPath??(data==null?"":data.Roots.FirstOrDefault())};loc.Controls.Add(path);loc.Controls.Add(UI.Button("Browse",()=>{string p=UI.Folder(path.Text);if(p!=null)path.Text=p;}));
   var split=new SplitContainer{Dock=DockStyle.Fill,SplitterWidth=4,FixedPanel=FixedPanel.Panel1};split.Size=new Size(1000,600);split.SplitterDistance=185;kinds=new ListBox{Dock=DockStyle.Fill,BorderStyle=BorderStyle.None,ItemHeight=UI.D(30),DrawMode=DrawMode.OwnerDrawFixed,IntegralHeight=false};foreach(string k in Reports.Names)kinds.Items.Add(k);kinds.DrawItem+=(s,e)=>{if(e.Index<0)return;var g=e.Graphics;var r=e.Bounds;bool sel=(e.State&DrawItemState.Selected)!=0;using(var b=new SolidBrush(Palette.Background))g.FillRectangle(b,r);if(sel){var h=new Rectangle(r.X+UI.D(4),r.Y+UI.D(1),r.Width-UI.D(8),r.Height-UI.D(2));Draw.Box(g,h,Palette.Selection,Palette.HoverBorder);}int sz=UI.D(16);g.DrawImage(Art.Icon(e.Index<5?"report":"chart"),r.X+UI.D(12),r.Y+(r.Height-sz)/2,sz,sz);Draw.Text(g,L.T((string)kinds.Items[e.Index]),Font,new Rectangle(r.X+UI.D(36),r.Y,r.Width-UI.D(40),r.Height),Palette.Text,Draw.Left);};split.Panel1.Controls.Add(kinds);
   var lower=new SplitContainer{Dock=DockStyle.Fill,Orientation=Orientation.Horizontal,FixedPanel=FixedPanel.Panel2};lower.Size=new Size(800,580);lower.SplitterDistance=410;grid=new ReportGrid(false);grid.Columns["Full Path"].Visible=true;Operations.Attach(grid,()=>displayedOffline||working,()=>Generate(true));lower.Panel1.Controls.Add(grid);chart=new SizeChart{Mode="Bar Chart"};lower.Panel2.Controls.Add(chart);split.Panel2.Controls.Add(lower);
   var options=new FlowLayoutPanel{Dock=DockStyle.Bottom,AutoSize=true,AutoSizeMode=AutoSizeMode.GrowAndShrink,WrapContents=true,Padding=new Padding(8,6,8,6)};options.Controls.Add(new Label{Text=L.T("Number of entries (0 = all)"),AutoSize=true,Anchor=AnchorStyles.Left,Margin=new Padding(4,0,4,0)});limit=new NumericUpDown{Minimum=0,Maximum=10000000,Value=100,Width=85,Anchor=AnchorStyles.Left};options.Controls.Add(limit);options.Controls.Add(new Label{Text=L.T("Compare by"),AutoSize=true,Anchor=AnchorStyles.Left,Margin=new Padding(18,0,4,0)});compare=new ComboBox{DropDownStyle=ComboBoxStyle.DropDownList,Width=210,Anchor=AnchorStyles.Left,Margin=new Padding(4,0,12,0)};compare.Items.AddRange(new object[]{"Name","Name + size","Name + size + modified","Content (SHA-256)"});L.TranslateCombo(compare);compare.SelectedIndex=1;options.Controls.Add(compare);options.Controls.Add(UI.Button("Generate",()=>Generate(false)));options.Controls.Add(UI.Button("Select all but first",SelectDuplicates));status=new Label{Dock=DockStyle.Bottom,Height=28,Padding=new Padding(8,0,0,0),TextAlign=ContentAlignment.MiddleLeft,Text=L.T("Ready")};Controls.Add(split);Controls.Add(options);Controls.Add(loc);Controls.Add(tool);Controls.Add(status);Palette.Apply(this);kinds.SelectedItem=initial;kinds.SelectedIndexChanged+=(s,e)=>Generate(false);Shown+=(s,e)=>{try{split.SplitterDistance=Math.Min(split.Width/3,UI.D(210));lower.SplitterDistance=Math.Max(UI.D(120),(int)(lower.Height*0.62));}catch{}Update();BeginInvoke(new Action(()=>Generate(false)));};FormClosing+=(s,e)=>{if(cancel!=null)cancel.Cancel();};grid.CellDoubleClick+=(s,e)=>Drill(e.RowIndex);
  }
  private async void Generate(bool rescan){if(working)return;if(kinds.SelectedItem==null)return;working=true;kinds.Enabled=location.Enabled=compare.Enabled=limit.Enabled=false;cancel=new CancellationTokenSource();try{status.Text=L.T("Scanning...");if(rescan||data==null){if(string.IsNullOrWhiteSpace(path.Text)){string p=UI.Folder("");if(p==null)return;path.Text=p;}string pth=path.Text;var options=UI.Clone(owner.Settings.Scan);data=await Task.Run(()=>new Scanner().Run(pth.Split('|'),options,cancel.Token));offline=false;}
    string kind=(string)kinds.SelectedItem,mode=(string)compare.SelectedItem;int max=(int)limit.Value;if(kind=="Duplicate Files"&&mode=="Content (SHA-256)"&&offline)throw new InvalidOperationException(L.T("Offline snapshots cannot be used to change live files."));Snapshot all=data;string scope=path.Text;Snapshot scoped=null;var rows=await Task.Run(()=>{scoped=string.IsNullOrWhiteSpace(scope)?all:all.Scope(scope.Split('|'));return Reports.Build(scoped,kind,max,mode,cancel.Token);});if(IsDisposed)return;grid.Columns["Information"].Visible=kind=="Duplicate Files";displayedData=scoped;displayedKind=kind;displayedOffline=offline;grid.SetData(rows);chart.Rows=rows;chart.Invalidate();status.Text=L.F("{0} items · {1}",rows.Count.ToString("N0"),Util.Size(rows.Sum(r=>r.Size)))+(data.Cancelled?" · "+L.T("Partial scan"):"");if(kind=="Duplicate Files"&&mode=="Content (SHA-256)"){int skipped=scoped.Events.Count(e=>e.Message==Reports.ContentSkippedMessage);if(skipped>0)status.Text+=" · "+L.F("{0} files not read (cloud, reparse or incomplete)",skipped);}
   }catch(OperationCanceledException){if(!IsDisposed)status.Text=L.T("Cancelled");}catch(Exception ex){if(!IsDisposed)UI.Error(ex);}finally{working=false;if(!IsDisposed)kinds.Enabled=location.Enabled=compare.Enabled=limit.Enabled=true;cancel.Dispose();cancel=null;}}
  private void SelectDuplicates(){if(displayedKind!="Duplicate Files")return;grid.ClearSelection();var groups=new HashSet<string>();for(int i=0;i<grid.Data.Count;i++)if(!groups.Add(grid.Data[i].Extra??""))grid.Rows[i].Selected=true;}
  private void Drill(int row){if(row<0||row>=grid.Data.Count||displayedData==null)return;var r=grid.Data[row];if(r.Source!=null){if(r.Source.Folder&&!displayedOffline){owner.Navigate(r.Path,true);}else if(!displayedOffline)UI.Shell(r.Path);return;}Dialogs.Rows(this,r.DisplayName,DrillRows(displayedData,displayedKind,r.Name));}
  internal static List<ReportRow> DrillRows(Snapshot scope,string kind,string name){
   Func<Entry,string> key=e=>e.Modified.Year.ToString();switch(kind){case "File Types":key=e=>string.IsNullOrEmpty(e.Extension)?"(no extension)":e.Extension;break;case "File Categories":key=Reports.Category;break;case "File Attributes":key=e=>e.AttrText;break;case "File Owners":key=e=>string.IsNullOrEmpty(e.Owner)?"(owner not collected)":e.Owner;break;case "File Sizes":key=e=>Reports.SizeBucket(e.Size);break;case "File Names":key=e=>e.Name;break;case "File Ages":key=e=>Reports.AgeBucket(e.Modified);break;case "File Depths":key=e=>"Depth "+e.Depth;break;}
   return scope.Entries.Where(e=>!e.Folder&&string.Equals(key(e),name,StringComparison.OrdinalIgnoreCase)).Select(Reports.Row).ToList();
  }
 }
 public class RuleEditor:UserControl {
  private DataGridView grid;private BindingList<Rule> rules;
  private class Choice {public string Id{get;set;}public string Text{get;set;}}
  public RuleEditor(IEnumerable<Rule> initial){Dock=DockStyle.Fill;rules=new BindingList<Rule>(initial.ToList());grid=new DataGridView{Dock=DockStyle.Fill,AutoGenerateColumns=false,AllowUserToAddRows=false,AllowUserToDeleteRows=false,RowHeadersVisible=false,BackgroundColor=Color.White,SelectionMode=DataGridViewSelectionMode.FullRowSelect,BorderStyle=BorderStyle.None};grid.Columns.Add(new DataGridViewCheckBoxColumn{Name="Enabled",HeaderText=L.T("Enabled"),Width=52});AddCombo("Action",new[]{"Include","Exclude"},85);AddCombo("Target",new[]{"Files","Folders","Both"},105);AddCombo("Field",new[]{"Name","Path","Extension","Size","Allocated","Depth","Path length","Name length","File count","Age days","Attributes","Owner"},130);AddCombo("Operator",new[]{"Wildcard","Regex","Contains","=","!=",">=","<=",">","<"},100);grid.Columns.Add(new DataGridViewTextBoxColumn{Name="Value",HeaderText=L.T("Value"),Width=170});grid.Columns.Add(new DataGridViewTextBoxColumn{Name="Description",HeaderText=L.T("Description"),AutoSizeMode=DataGridViewAutoSizeColumnMode.Fill});
   foreach(Rule r in rules)AddRow(r);var bar=new FlowLayoutPanel{Dock=DockStyle.Bottom,Height=43};bar.Controls.Add(UI.Button("Add",()=>AddRow(new Rule())));bar.Controls.Add(UI.Button("Remove",()=>{foreach(DataGridViewRow r in grid.SelectedRows)if(!r.IsNewRow)grid.Rows.Remove(r);}));bar.Controls.Add(UI.Button("Save",()=>{using(var d=new SaveFileDialog{Filter="XML (*.xml)|*.xml"})if(d.ShowDialog()==DialogResult.OK)AtomicXml.Write(Read(),d.FileName);}));bar.Controls.Add(UI.Button("Load",()=>{using(var d=new OpenFileDialog{Filter="XML (*.xml)|*.xml"})if(d.ShowDialog()==DialogResult.OK){var list=AtomicXml.Read<List<Rule>>(d.FileName);Rules.Validate(list);grid.Rows.Clear();foreach(var r in list)AddRow(r);}}));var note=new Label{Dock=DockStyle.Top,Height=40,Padding=new Padding(8),Text=L.T("Rules are OR-combined; exclusions take priority. Numeric sizes are bytes.")};Controls.Add(grid);Controls.Add(note);Controls.Add(bar);Palette.Apply(this);}
  private void AddCombo(string name,string[] values,int width){grid.Columns.Add(new DataGridViewComboBoxColumn{Name=name,HeaderText=L.T(name),Width=width,DataSource=values.Select(s=>new Choice{Id=s,Text=L.T(s)}).ToList(),DisplayMember="Text",ValueMember="Id",FlatStyle=FlatStyle.Flat});}
  private void AddRow(Rule r){grid.Rows.Add(r.Enabled,r.Action,r.Target,r.Field,r.Operator,r.Value,r.Description);}
  public List<Rule> Read(){grid.EndEdit();var result=new List<Rule>();foreach(DataGridViewRow row in grid.Rows)if(!row.IsNewRow)result.Add(new Rule{Enabled=Convert.ToBoolean(row.Cells[0].Value),Action=Convert.ToString(row.Cells[1].Value),Target=Convert.ToString(row.Cells[2].Value),Field=Convert.ToString(row.Cells[3].Value),Operator=Convert.ToString(row.Cells[4].Value),Value=Convert.ToString(row.Cells[5].Value),Description=Convert.ToString(row.Cells[6].Value)});Rules.Validate(result);return result;}
 }
 public class SearchForm:Form {
  private MainForm main;private Snapshot data;private bool offline,displayedOffline,zip;private RuleEditor rules;private ReportGrid grid;private ComboBox path;private Label status;private CancellationTokenSource cancel;private bool working;
  public SearchForm(MainForm owner,bool zipMode){main=owner;data=owner.Data;offline=displayedOffline=owner.Offline;zip=zipMode;Text=L.T(zip?"Filter & Zip":"Search files and folders");Size=new Size(1150,780);MinimumSize=new Size(850,600);Font=new Font("Segoe UI",9);AutoScaleDimensions=new SizeF(96,96);AutoScaleMode=AutoScaleMode.Dpi;StartPosition=FormStartPosition.CenterParent;
   var tool=new ToolStrip{Dock=DockStyle.Top,GripStyle=ToolStripGripStyle.Hidden,ImageScalingSize=new Size(UI.D(16),UI.D(16))};tool.Items.Add(UI.Tool("Search current snapshot","search",()=>Search(false)));tool.Items.Add(UI.Tool("Scan first","play",()=>Search(true)));tool.Items.Add(UI.Tool("Stop","stop",()=>{if(cancel!=null)cancel.Cancel();}));tool.Items.Add(UI.Tool("Export","export",()=>UI.Export(this,Text,grid.Data)));tool.Items.Add(UI.Tool("Print","print",()=>UI.Print(this,Text,grid.Data)));tool.Items.Add(UI.Tool("Create ZIP","zip",()=>{if(grid.Selected().Count==0)grid.SelectAll();Operations.Execute("Archive",grid,displayedOffline||working,()=>Search(true));}));
   var loc=new TableLayoutPanel{Dock=DockStyle.Top,AutoSize=true,AutoSizeMode=AutoSizeMode.GrowAndShrink,ColumnCount=2,Padding=new Padding(6,4,6,4)};loc.ColumnStyles.Add(new ColumnStyle(SizeType.Percent,100));loc.ColumnStyles.Add(new ColumnStyle(SizeType.AutoSize));path=new ComboBox{Anchor=AnchorStyles.Left|AnchorStyles.Right,Text=owner.CurrentPath??(data==null?"":data.Roots.First())};loc.Controls.Add(path);loc.Controls.Add(UI.Button("Browse",()=>{string p=UI.Folder(path.Text);if(p!=null)path.Text=p;}));
   var split=new SplitContainer{Dock=DockStyle.Fill,Orientation=Orientation.Horizontal,SplitterWidth=4};split.Size=new Size(1050,650);split.SplitterDistance=210;rules=new RuleEditor(new[]{new Rule{Field="Name",Operator="Wildcard",Value="*",Target="Files"}});grid=new ReportGrid(false);grid.Columns["Full Path"].Visible=true;Operations.Attach(grid,()=>displayedOffline||working,()=>Search(true));split.Panel1.Controls.Add(rules);split.Panel2.Controls.Add(grid);status=new Label{Dock=DockStyle.Bottom,Height=28,Padding=new Padding(7),Text=L.T("Ready")};Controls.Add(split);Controls.Add(loc);Controls.Add(tool);Controls.Add(status);Palette.Apply(this);FormClosing+=(s,e)=>{if(cancel!=null)cancel.Cancel();};}
  private async void Search(bool scan){if(working)return;working=true;cancel=new CancellationTokenSource();try{List<Rule> rr=rules.Read();status.Text=L.T("Scanning...");if(scan||data==null){string p=path.Text;if(string.IsNullOrWhiteSpace(p)){p=UI.Folder("");if(p==null)return;path.Text=p;}ScanOptions opt=UI.Clone(main.Settings.Scan);data=await Task.Run(()=>new Scanner().Run(p.Split('|'),opt,cancel.Token));offline=false;}Snapshot all=data;string scope=path.Text;var result=await Task.Run(()=>{Snapshot scoped=string.IsNullOrWhiteSpace(scope)?all:all.Scope(scope.Split('|'));return scoped.Entries.Where(e=>Rules.Accept(e,rr)).Select(Reports.Row).ToList();});if(IsDisposed)return;displayedOffline=offline;grid.SetData(result);status.Text=L.F("{0} items · {1}",result.Count.ToString("N0"),Util.Size(result.Where(r=>r.Source!=null&&!r.Source.Folder).Sum(r=>r.Size)));}catch(OperationCanceledException){if(!IsDisposed)status.Text=L.T("Cancelled");}catch(Exception ex){if(!IsDisposed)UI.Error(ex);}finally{working=false;}}
 }
}
